trial.program_source:
def transform(grid):
    color=None
    for row in grid:
        a=[v for v in row if v]
        if len(a)==3:
            color=a[1];break
    if color is None:
        for col in zip(*grid):
            a=[v for v in col if v]
            if len(a)==3:
                color=a[1];break
    return [[v if v==color else 0 for v in row] for row in grid]

